// stores/productStore.js
import { createStore } from "vuex";
import { productService } from "@/services/product"; // 引入产品服务

const productStore = createStore({
    state: {
        products: [], // 存储产品列表
        selectedProduct: null, // 存储当前选中的产品信息
    },
    mutations: {
        setProducts(state, products) {
            state.products = products; // 设置产品列表
        },
        setSelectedProduct(state, product) {
            state.selectedProduct = product; // 设置选中的产品信息
        },
        clearSelectedProduct(state) {
            state.selectedProduct = null; // 清空选中的产品
        },
    },
    actions: {
        async fetchProducts({ commit }) {
            try {
                const response = await productService.fetchProducts(); // 从服务中获取产品数据
                commit("setProducts", response.data); // 提交变更设置产品列表
            } catch (error) {
                console.error("获取产品列表失败:", error);
                throw new Error("获取产品失败"); // 在组件中可以捕获处理
            }
        },
        async fetchProductDetails({ commit }, productId) {
            try {
                const response = await productService.fetchProductDetails(productId);
                commit("setSelectedProduct", response.data); // 提交变更设置选中产品
            } catch (error) {
                console.error("获取产品详情失败:", error);
            }
        },
        async createProduct({ dispatch }, productData) {
            try {
                await productService.createProduct(productData); // 创建新产品
                await dispatch("fetchProducts"); // 更新产品列表
            } catch (error) {
                console.error("创建产品失败:", error);
            }
        },
        async updateProduct({ dispatch }, { productId, updatedData }) {
            try {
                await productService.updateProduct(productId, updatedData); // 更新产品
                await dispatch("fetchProducts"); // 更新产品列表
            } catch (error) {
                console.error("更新产品失败:", error);
            }
        },
        async deleteProduct({ dispatch }, productId) {
            try {
                await productService.deleteProduct(productId); // 删除产品
                await dispatch("fetchProducts"); // 更新产品列表
            } catch (error) {
                console.error("删除产品失败:", error);
            }
        },
    },
    getters: {
        allProducts(state) {
            return state.products; // 返回所有产品
        },
        selectedProduct(state) {
            return state.selectedProduct; // 返回选中的产品信息
        },
        productCount(state) {
            return state.products.length; // 返回产品数量
        },
    },
});

export default productStore;
